// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(this)); // actor is not the admin/deployer
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));

        // admin transfers ownership to the fuzzed actor (succeeds in both versions)
        vm.prank(address(this));
        c.setOwner(actor);
        assertEq(c.owner(), actor);

        // the (non-admin) current owner tries to change the owner again:
        // the reference must reject it; only the buggy mutant accepts it
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "non-admin must not be able to call setOwner");
    }
}
